import { sortedNames } from './parse.js'

/** The dependencies of a task in ascending order. */
export function depsOf(tasks, name) {
  return [...tasks.get(name).deps].sort()
}

/**
 * Throws when the graph holds a cycle. The reported cycle is the first one a
 * depth-first search finds when it starts from each task in ascending name
 * order and walks each task's dependencies in ascending name order.
 */
export function checkAcyclic(tasks) {
  const state = new Map()
  for (const name of tasks.keys()) state.set(name, 0)

  for (const root of sortedNames(tasks)) {
    if (state.get(root) !== 0) continue
    const path = []
    const frames = [{ node: root, deps: depsOf(tasks, root), i: 0 }]
    state.set(root, 1)
    path.push(root)
    while (frames.length > 0) {
      const frame = frames[frames.length - 1]
      if (frame.i < frame.deps.length) {
        const next = frame.deps[frame.i]
        frame.i += 1
        const mark = state.get(next)
        if (mark === 1) {
          const start = path.indexOf(next)
          throw cycleError([...path.slice(start), next])
        }
        if (mark === 0) {
          state.set(next, 1)
          path.push(next)
          frames.push({ node: next, deps: depsOf(tasks, next), i: 0 })
        }
      } else {
        state.set(frame.node, 2)
        path.pop()
        frames.pop()
      }
    }
  }
}

/** Folds a value over each task from its dependencies upward. */
function foldUp(tasks, edgesOf, combine) {
  const value = new Map()
  for (const root of sortedNames(tasks)) {
    if (value.has(root)) continue
    const frames = [{ node: root, next: edgesOf(root), i: 0 }]
    while (frames.length > 0) {
      const frame = frames[frames.length - 1]
      if (frame.i < frame.next.length) {
        const other = frame.next[frame.i]
        frame.i += 1
        if (!value.has(other)) frames.push({ node: other, next: edgesOf(other), i: 0 })
      } else {
        frames.pop()
        if (!value.has(frame.node)) {
          value.set(frame.node, combine(frame.node, frame.next.map((n) => value.get(n))))
        }
      }
    }
  }
  return value
}

/** The tasks that depend on each task, in ascending order. */
export function dependents(tasks) {
  const map = new Map()
  for (const name of tasks.keys()) map.set(name, [])
  for (const name of sortedNames(tasks)) {
    for (const dep of depsOf(tasks, name)) map.get(dep).push(name)
  }
  return map
}

/**
 * The schedule with unlimited workers: for every task its start, finish and
 * the wave (depth) it sits in.
 */
export function analyse(tasks) {
  const edgesOf = (name) => depsOf(tasks, name)
  const finish = foldUp(tasks, edgesOf, (name, values) => {
    const start = values.length === 0 ? 0 : Math.max(...values)
    return start + tasks.get(name).cost
  })
  const depth = foldUp(tasks, edgesOf, (name, values) =>
    values.length === 0 ? 0 : Math.max(...values) + 1,
  )
  const info = new Map()
  let total = 0
  for (const name of sortedNames(tasks)) {
    const f = finish.get(name)
    info.set(name, { name, start: f - tasks.get(name).cost, finish: f, depth: depth.get(name) })
    if (f > total) total = f
  }
  return { info, total }
}

/**
 * The priority of each task: the cost of the longest chain that begins at it,
 * counting its own cost and the costs down to any task nothing depends on.
 */
export function priorities(tasks) {
  const down = dependents(tasks)
  return foldUp(tasks, (name) => down.get(name), (name, values) => {
    const rest = values.length === 0 ? 0 : Math.max(...values)
