  try {
    return readFileSync(0, 'utf8')
  } catch {
    return ''
  }
}

function renderWaves(tasks) {
  const { info, total } = analyse(tasks)
  const waves = []
  for (const name of sortedNames(tasks)) {
    const depth = info.get(name).depth
    while (waves.length <= depth) waves.push([])
    waves[depth].push(name)
  }
  const lines = waves.map((names, k) => `wave ${k}: ${names.join(' ')}`)
  lines.push(`total ${total}`)
  return lines
}

