  const { info, total } = analyse(tasks)
  const lines = sortedNames(tasks).map((name) => {
    const it = info.get(name)
    return `${name} start=${it.start} finish=${it.finish} depth=${it.depth}`
  })
  lines.push(`total ${total}`)
  return lines
}

function renderPack(tasks, workers) {
  const { runs, makespan } = pack(tasks, workers)
  const lines = runs.map((run, i) => {
    const parts = run.map((r) => ` ${r.name}@${r.start}-${r.finish}`).join('')
    return `worker ${i}:${parts}`
  })
  lines.push(`makespan ${makespan}`)
  return lines
