import { readFileSync } from 'node:fs'
import { CliError, fail } from './errors.js'
import { parseGraph, sortedNames } from './parse.js'
import { analyse, checkAcyclic } from './graph.js'
import { pack } from './schedule.js'

const USAGE = 'usage: cli.js waves|explain|pack <workers>'

function parseArgs(argv) {
  if (argv.length === 1 && (argv[0] === 'waves' || argv[0] === 'explain')) {
    return { mode: argv[0] }
  }
  if (argv.length === 2 && argv[0] === 'pack') {
    if (!/^[1-9][0-9]*$/.test(argv[1])) throw fail('workers must be a positive integer')
    return { mode: 'pack', workers: Number(argv[1]) }
  }
  throw fail(USAGE)
}

function readStdin() {
  try {
    return readFileSync(0, 'utf8')
  } catch {
    return ''
  }
}

function renderWaves(tasks) {
  const { info, total } = analyse(tasks)
  const waves = []
  for (const name of sortedNames(tasks)) {
    const depth = info.get(name).depth
    while (waves.length <= depth) waves.push([])
    waves[depth].push(name)
  }
  const lines = waves.map((names, k) => `wave ${k}: ${names.join(' ')}`)
  lines.push(`total ${total}`)
  return lines
}

